"""Floating sky rocks (your art): obstacles that drift across the Sky Islands sky. Touching one hurts you;
breath, dashes and Ultimates destroy them and they crumble apart into tumbling chunks of rock.
They live in game.enemies with 'isle': kind, so every attack and the heart/shield rules already work on them."""
import base64
import math
import random
import zlib
import pygame
from fd_core import WIDTH, HEIGHT, GROUND_Y
from fd_sound import AUDIO

KINDS = tuple('rock%d' % i for i in range(1, 12))
DATA = {
  'rock1': (47, 83, ''),
  'rock2': (42, 66, ''),
  'rock3': (45, 67, ''),
  'rock4': (81, 112, ''),
  'rock5': (50, 59, ''),
  'rock6': (39, 60, ''),
  'rock7': (67, 92, ''),
  'rock8': (28, 37, ''),
  'rock9': (38, 57, ''),
  'rock10': (114, 101, ''),
  'rock11': (98, 116, ''),
}
BOX_FRAC = (0.78, 0.72)           # hit box: the solid middle of the rock (fraction of the picture's size)
PTS = 40
DUST = ((150, 146, 140), (110, 106, 100), (120, 170, 90), (180, 176, 168))
CRYSTAL = ((120, 200, 255), (60, 150, 250), (220, 248, 255))
_C = {}


def frame(kind, i=0):
  s = _C.get(kind)
  if s is None:
    w, h, data = DATA[kind]
    s = pygame.image.frombuffer(zlib.decompress(base64.b64decode(data)), (w, h), 'RGBA').copy()
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[kind] = s
  return s


def box(kind):
  w, h, _d = DATA[kind]
  return max(18, int(w * BOX_FRAC[0])), max(18, int(h * BOX_FRAC[1]))


def on_screen(game):
  return any(e.get('isle') and not e.get('shattered') for e in game.enemies)


def pool_for(game):
  """the Sky Islands sky sends floating rocks at you (one at a time)"""
  if game.world() != 'skyisle' or on_screen(game):
    return []
  return ['isle'] * (2 if game.threat < 3 else 3)


def spawn(game, kind=None):
  kind = kind or random.choice(KINDS)
  bw, bh = box(kind)
  y = random.randint(40, max(41, GROUND_Y - bh - 90))
  x = WIDTH + 40
  game.enemies.append({'rect': pygame.Rect(x, y, bw, bh), 'fx': float(x), 'isle': kind, 'foe': 'isle', 'by': float(y),
                       'speed': 2.2 + game.threat * 0.18 + random.uniform(-0.3, 0.4), 'passed': False, 'state': 'normal',
                       'vy': 0.0, 'phase': random.uniform(0, 6.28), 'age': random.uniform(0, 60)})


def ai(game, e):
  """drifts across slowly with a gentle bob"""
  e['age'] += game.ts
  e['fx'] -= e['speed'] * game.ts
  r = e['rect']
  r.x = int(e['fx'])
  r.y = int(e['by'] + math.sin(e['age'] * 0.035 + e['phase']) * 12)


def sprite_pos(e, spr=None):
  spr = spr or frame(e['isle'])
  r = e['rect']
  return r.centerx - spr.get_width() // 2, r.centery - spr.get_height() // 2


def draw(gs, game, e):
  spr = frame(e['isle'])
  gs.blit(spr, sprite_pos(e, spr))


def corpse(game, e):
  """crumbles: the rock splits into pieces that tumble away, with a burst of dust and grit"""
  spr = frame(e['isle'])
  x, y = sprite_pos(e, spr)
  game.break_apart(spr, x, y, step=14 if spr.get_width() < 70 else 18, power=1.25)
  r = e['rect']
  for _ in range(16 + r.w // 6):
    game.emit(r.centerx + random.randint(-r.w // 2, r.w // 2), r.centery + random.randint(-r.h // 2, r.h // 2),
              random.uniform(-3, 3), random.uniform(-3.5, 0.5), random.randint(6, 14), random.choice(DUST))
  if e['isle'] in ('rock10', 'rock11'):            # (these two have blue crystals)
    game.burst(r.centerx, r.bottom - 10, 14, 5, 4, 10, random.choice(CRYSTAL))
  game.shake_for(6, 8)
  AUDIO.play('shatter', 0.8)
